def largestMultipleOfThree(digits):
    d = sorted(digits, reverse=True)
    r = sum(d) % 3

    def remove(rem, cnt):
        idx = [i for i in range(len(d) - 1, -1, -1) if d[i] % 3 == rem][:cnt]
        if len(idx) < cnt:
            return False
        for i in sorted(idx, reverse=True):
            del d[i]
        return True

    if r and not remove(r, 1):
        if not remove(3 - r, 2):
            return []
    if not d:
        return []
    if d[0] == 0:
        return [0]
    return d
